<script setup lang="ts">
import { onMounted,ref } from 'vue'; import { getSystemConfigurations,saveSystemConfigurations } from '../../api/modules/settings'; import type { SystemConfiguration } from '../../types/settings'
const groups=ref<SystemConfiguration[]>([]),saved=ref(''); onMounted(async()=>groups.value=await getSystemConfigurations()); async function save(){await saveSystemConfigurations(groups.value);saved.value='配置已保存';setTimeout(()=>saved.value='',1800)} async function reset(){groups.value=await getSystemConfigurations();saved.value='已恢复当前保存值'}
</script>
<template><section class="settings-page"><header class="settings-page__header"><div><p class="page-eyebrow">SYSTEM CONFIGURATION</p><h1>配置管理</h1></div><div class="settings-header-actions"><span>{{saved}}</span><button @click="reset">恢复</button><button class="settings-primary" @click="save">保存更改</button></div></header><div class="configuration-grid"><section v-for="group in groups" :key="group.group"><header>{{group.group}}</header><div><label v-for="item in group.items" :key="item.key"><span><strong>{{item.key}}</strong><small>修改后记录操作日志</small></span><select v-if="item.options" v-model="item.value"><option v-for="option in item.options" :key="option">{{option}}</option></select><input v-else v-model="item.value"></label></div></section></div></section></template>
